mapper.sql:
l.deleted = 0

    AND l.app_id = #{appId}


    AND l.module LIKE CONCAT('%', #{module}, '%')


    AND l.operator_username LIKE CONCAT('%', #{operator}, '%')


    AND l.operation_type = #{operationType}


    AND l.status = #{status}


    AND l.operated_at >= CONCAT(#{startTime}, ' 00:00:00')


    AND l.operated_at < DATE_ADD(#{endTime}, INTERVAL 1 DAY)

mapper.update:
UPDATE sys_operation_log SET deleted = 1
WHERE id IN

    #{id}
